import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('re-exports the list_sessions and session_list frame types in IncomingMessage and OutgoingMessage', () => {
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 3,
    };
    const listRequest: ListSessionsMessage = {type: 'list_sessions', limit: 10, before: summary};
    const listReply: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const incoming: IncomingMessage[] = [
      {type: 'user_message', content: 'hello'},
      {type: 'ping', timestamp: 1},
      listRequest,
    ];
    const outgoing: OutgoingMessage[] = [{type: 'stream_end'}, listReply];

    expect({
      incomingTypes: incoming.map(frame => frame.type),
      outgoingTypes: outgoing.map(frame => frame.type),
      sessions: listReply.sessions,
    }).toEqual({
      incomingTypes: ['user_message', 'ping', 'list_sessions'],
      outgoingTypes: ['stream_end', 'session_list'],
      sessions: [summary],
    });
  });
});

